import json,subprocess,sys,pathlib,decimal
from decimal import Decimal,ROUND_HALF_EVEN
inputs=['1.365','1.36500000000001','1.36500000000005','1.36500000000009','1.375','2.675','-1.365','0.125','1.005']
py={}
for s in inputs:
    f=float(s)
    py[s]={'decimal_from_text':str(Decimal(s).quantize(Decimal('0.01'),ROUND_HALF_EVEN)),'decimal_from_str_float':str(Decimal(str(f)).quantize(Decimal('0.01'),ROUND_HALF_EVEN)),'exact_binary_value':str(Decimal(f)),'builtin_round_float':repr(round(f,2))}
js='''
function bankersRound(n,d=2){var x=n*Math.pow(10,d);var r=Math.round(x);var br=Math.abs(x)%1===0.5?(r%2===0?r:r-1):r;return br/Math.pow(10,d);}
function textHalfEven(s,d){let neg=s[0]==='-';if(neg)s=s.slice(1);let [i,f='']=s.split('.');f=f.padEnd(d+1,'0');let scaled=BigInt(i+f.slice(0,d));let rest=f.slice(d);let first=rest.charCodeAt(0)-48;let tailNonZero=/[1-9]/.test(rest.slice(1));if(first>5||(first===5&&(tailNonZero||scaled%2n===1n)))scaled+=1n;let t=scaled.toString().padStart(d+1,'0');let out=t.slice(0,t.length-d)+'.'+t.slice(t.length-d);return (neg&&scaled!==0n?'-':'')+out;}
const inputs=JSON.parse(process.argv[1]);const o={};
for(const s of inputs){const n=Number(s);o[s]={x_times_100:String(n*100),question_bankersRound:String(bankersRound(n,2)),toFixed2:n.toFixed(2),text_half_even:textHalfEven(s,2)};}
console.log(JSON.stringify(o));
'''
r=subprocess.run(['node','-e',js,json.dumps(inputs)],capture_output=True,text=True)
node=json.loads(r.stdout) if r.returncode==0 else {'error':r.stderr[-500:]}
nv=subprocess.run(['node','--version'],capture_output=True,text=True).stdout.strip()
rows=[];mism=0;par=0
for s in inputs:
    a=py[s]['decimal_from_text'];b=node.get(s,{}).get('question_bankersRound');c=node.get(s,{}).get('text_half_even')
    q=(Decimal(b)==Decimal(a)) if b else None
    t=(c==a) if c else None
    mism+= (q is False);par+=(t is True)
    rows.append({'input':s,'python':py[s],'node':node.get(s),'question_fn_matches_python_decimal':q,'text_half_even_matches_python_decimal':t})
out={'python_version':sys.version.split()[0],'node_version':nv,'inputs':inputs,'rows':rows,'question_fn_mismatches':int(mism),'text_half_even_matches':int(par),'n':len(inputs)}
p=pathlib.Path('products/services/parser-parity/request-fit/repro.json');p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(out,indent=1))
print(json.dumps(out))
